{
  "searches": [
    {
      "reason": "Replace scale-dependent training margins with a ranking audit that measures sensitivity to candidate difficulty and popularity. Seek practical comparisons between sampled rankings and full-catalog unseen-item rankings, including user-level uncertainty and history-length strata. Keep training-user audits separate from pinned validation HR@10 and leave the host evaluator unchanged.",
      "query": "sequential recommendation diagnostic evaluation sampled versus full catalog ranking popularity matched hard negatives rank disagreement bootstrap uncertainty 2024 2025 2026"
    },
    {
      "reason": "Develop evidence-grounded probes for the reported failures: broad relevance outranking specific interests, unsupported equipment assumptions, and potentially redundant recommendations. Investigate training-only TF-IDF, explicit specification extraction, and interaction evidence to distinguish supported connections, documented contradictions, and unknown requirements. Validate against explicit feedback where available; never infer ownership, satisfied needs, compatibility, or latent traits from missing evidence.",
      "query": "recommendation explanation faithfulness evidence grounded diagnostic evaluation user feedback specificity complementary substitute products compatibility uncertainty abstention without pretrained models 2024 2025 2026"
    },
    {
      "reason": "Build an intervention-based diagnostic suite that distinguishes useful personalization from popularity shortcuts and connects failures to encoder, recent-history branch, and scoring components. Seek matched-history controls, component ablations, and synthetic positive/negative controls to validate probe sensitivity. Require deterministic, state-preserving execution through DiagnosisProbe; recommendation stability alone must not count as success, and acute interventions must not be interpreted as causal preference effects.",
      "query": "sequential recommender diagnostic probes matched history interventions popularity shortcuts component ablation activation patching sanity checks metric validation 2024 2025 2026"
    }
  ]
}
